import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { debitAccountsWorkflow } from "@medusajs/loyalty-plugin/workflows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await debitAccountsWorkflow(req.scope)
    .run({
      input: [{
        account_id: "sca_123",
        amount: 50,
        reference: "cart",
        reference_id: "cart_123",
      }, ],
    })

  res.send(result)
}

